const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const board=(title,lines)=>({t:'board',title,lines});
const flow=(title,labels,details)=>{const pts={},polys=[],segs=[],notes=[];labels.forEach((label,i)=>{const x=i*36;for(const [j,xy] of [[0,[x,15]],[1,[x+28,15]],[2,[x+28,27]],[3,[x,27]]])pts['ABCD'[j]+i]=xy;polys.push({v:`A${i}B${i}C${i}D${i}`,label,col:i});notes.push({at:[x+14,7],text:details[i]});if(i<2){pts['P'+i]=[x+29,21];pts['Q'+i]=[x+35,21];segs.push({v:`P${i}Q${i}`,arrows:1,col:i});}});return {t:'figure',title,view:[-3,103,0,34],pts,polys,segs,notes,dots:'',hide:Object.keys(pts).join('')};};
const illustrated=(title,src,label,lines)=>[{t:'art',title,items:[{src:`ap-world/${src}.png`,x:130,y:219,h:src==='migration-steamship'?120:140,label}]},{t:'figure',view:[0,100,0,36],pts:{},dots:'',notes:lines.map((text,i)=>({at:[68,29-i*8],text}))}];
const chronology={t:'figure',title:'Changes in imperial control (years to scale)',view:[1790,1915,-25,25],pts:{A:[1799,0],B:[1908,0],C:[1858,0],D:[1885,0]},hide:'ABCD',dots:'ABCD',segs:[{v:'AB',arrows:1}],notes:[{at:[1804,15],text:'1799: VOC ends'},{at:[1858,-15],text:'1858: Crown rule in India'},{at:[1879,15],text:'1885: Congo Free State'},{at:[1894,-23],text:'1908: Belgian annexation'}]};
const exports={t:'chart',kind:'bars',title:'Fictional export earnings (units of account)',max:100,bars:[{label:'Crop, earlier',value:30},{label:'Other, earlier',value:30},{label:'Crop, later',value:90},{label:'Other, later',value:30}]};
const migrationLinks={t:'figure',title:'Migration and remittances move in different directions',view:[0,100,0,36],pts:{A:[1,9],B:[26,9],C:[26,28],D:[1,28],E:[74,9],F:[99,9],G:[99,28],H:[74,28],P:[28,24],Q:[72,24],R:[72,13],S:[28,13]},hide:'ABCDEFGHPQRS',dots:'',polys:[{v:'ABCD',label:'Origin',col:0},{v:'EFGH',label:'Destination',col:1}],segs:[{v:'PQ',arrows:1,col:0},{v:'RS',arrows:1,col:1}],notes:[{at:[50,29],text:'Workers move'},{at:[50,8],text:'Earnings sent home'},{at:[13,3],text:'Household ties'},{at:[87,3],text:'Jobs / communities'}]};
const tradeEvidence={t:'chart',kind:'bars',title:'Fictional trade values (units of account)',max:60,bars:[{label:'Exports, early',value:20},{label:'Exports, late',value:50},{label:'Imports, early',value:10},{label:'Imports, late',value:40}]};
const TRY=[
 ['A fictional local council petitions an imperial governor to restore confiscated farmland. What does the petition demonstrate?','resistance could use political appeals as well as fighting',['all resistance required battlefield victory','the council accepted confiscation without objection'],'Identify the action taken by the council rather than assuming resistance must be military.',board('Fictional petition',['Council demands return of seized farmland','Appeal is addressed to an imperial governor','Classify the method of opposition'])],
 ['A fictional passenger ledger records a worker leaving for a harvest job and returning home afterward. Which migration pattern fits?','temporary labor migration',['permanent settlement with no return','forced transport of a convicted prisoner'],'Separate the duration of migration from the reason for moving.',flow('Fictional worker’s journey',['Home','Harvest work','Home again'],['Departure','Job abroad','Return'])],
 ['A fictional colony exports more ore after a railway opens, but company accounts show most profits leaving the colony. Which claim fits both sources?','greater exports could coexist with unequal gains',['higher exports prove equal gains for all residents','the railway prevented all overseas trade'],'An increase in trade volume does not identify who received the income.',board('Fictional paired sources',['Freight log: ore exports increase','Accounts: most profits go abroad','Use both sources to qualify the claim'])]
];
const check=i=>{const [q,right,wrong,hint,pic]=TRY[i],c=choose(right,wrong,i);return {prompt:`Try it: ${q[0].toLowerCase()+q.slice(1)} ${c.text}. Answer A, B or C.`,answer:c.letter,options:['A','B','C'],hint,pic};};
